    image_patch = ImagePatch(image)
    sheep_patches = image_patch.find("sheep")
    if len(sheep_patches) < 2:
        return image_patch  # Not enough sheep to compare

    # Sort patches by vertical center to find pairs
    sheep_patches.sort(key=lambda p: p.vertical_center)

    # Check if the pairs are next to each other
    for i in range(len(sheep_patches) - 1):
        if sheep_patches[i].overlaps_with(0, 0, 0, 0, sheep_patches[i + 1]):
            return sheep_patches[i]

    return sheep_patches[0]  # Return the first sheep if no pair found

